@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 120 20% 10%;

    --primary: 154 100% 25%;
    --primary-foreground: 0 0% 100%;

    --secondary: 33 75% 80%;
    --secondary-foreground: 120 20% 10%;

    --accent: 154 100% 25%;
    --accent-foreground: 0 0% 100%;

    --muted: 120 10% 90%;
    --muted-foreground: 120 10% 40%;

    --card: 0 0% 100%;
    --card-foreground: 120 20% 10%;

    --border: 120 10% 90%;
    --input: 120 10% 90%;
    --ring: 154 100% 25%;

    --radius: 0.5rem;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-family: 'Instrument Sans', sans-serif;
  }
  h1, h2, h3, h4, h5, h6 {
    font-family: 'Clash Display', sans-serif;
  }
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center whitespace-nowrap rounded-full text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "bg-brand-green text-white hover:bg-brand-green/90",
        destructive: "bg-red-500 text-white hover:bg-red-500/90",
        outline: "border border-brand-green text-brand-green hover:bg-brand-green/10",
        secondary: "bg-brand-cream text-brand-dark hover:bg-brand-cream/80",
        ghost: "hover:bg-brand-green/10 text-brand-green",
        link: "text-brand-green underline-offset-4 hover:underline",
      },
      size: {
        default: "h-10 px-6 py-2",
        sm: "h-9 px-4",
        lg: "h-12 px-8 text-base",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    return (
      <button
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = "Button"

export { Button, buttonVariants }

/** @type {import('tailwindcss').Config} */
module.exports = {
